WITH b AS (SELECT c.ano,c.id_municipio,m.nome municipio,c.valor_total_estimado,c.valor_total_homologado,LOWER(REGEXP_REPLACE(COALESCE(c.objeto_compra,''),r'mata de são joão|mata de sao joao','')) texto FROM `basedosdados.br_mgi_pncp.contratacao` c JOIN `basedosdados.br_bd_diretorios_brasil.municipio` m ON c.id_municipio=m.id_municipio WHERE c.ano BETWEEN 2021 AND 2026 AND m.sigla_uf='BA'),f AS (SELECT *,CASE WHEN REGEXP_CONTAINS(texto,r'\bcarnaval\b|\bsão joão\b|\bsao joao\b|\bfesta junina\b|\bfestas juninas\b|\bfestividade|\bfestejo|\bfesta popular|\bfestas populares|\bfestas tradicionais|\bcomemoração de .*?(festa|evento|aniversário|aniversario)|\bcomemoracao de .*?(festa|evento|aniversario)|\barr[aá]i[aá]\b|\br[eé]veillon\b') THEN 1 WHEN REGEXP_CONTAINS(texto,r'\bartista\b|\bartistas\b|\bcantor\b|\bcantora\b|\bbanda\b|\bm[uú]sico\b|\bm[uú]sica\b|\bdupla\b|\bdj\b|\bservi[cç]o[s]? art[ií]stico|\bapresenta[cç][aã]o musical\b|\batra[cç][aã]o musical\b') THEN 1 WHEN REGEXP_CONTAINS(texto,r'\bshow\b|\bshows\b|\bespet[aá]culo\b|\bfestival\b|\bprodu[cç][aã]o de evento\b|\borganiza[cç][aã]o de evento\b|\brealiza[cç][aã]o de evento\b|\bevento cultural\b|\bevento festivo\b') THEN 1 WHEN REGEXP_CONTAINS(texto,r'\bpalco\b|\bsonoriza[cç][aã]o\b|\bsom para (evento|festa|show)\b|\bilumina[cç][aã]o c[eé]nica\b|\btenda[s]?\b|\btoldos?\b|\btrio el[eé]trico\b|\bbanheiro[s]? qu[ií]mico[s]?\b|\bgerador para (evento|festa|show)\b|\bestrutura (para|de) (evento|festa|show)\b|\bloc[aç][aã]o de estrutura') AND REGEXP_CONTAINS(texto,r'evento|festa|show|festival|carnaval|s[aã]o jo[aã]o|festiv') THEN 1 END ok FROM b),x AS (SELECT * FROM f WHERE ok=1)
SELECT municipio,COUNT(*) quantidade,COUNTIF(valor_total_homologado IS NOT NULL) qtd_homologado,SUM(valor_total_homologado) valor_homologado,SUM(valor_total_estimado) valor_estimado FROM x GROUP BY municipio ORDER BY quantidade DESC LIMIT 20